/// @file molrs.hpp
/// @brief Stable public header for the molrs CXX FFI layer.
///
/// Include this file instead of the generated bridge header.
/// The bridge is always double-precision: molrs-core hardcodes F = f64,
/// so a single generated bridge serves every build config (zero-copy on
/// the default double CPU tiers). See the corrosion wiring in the root
/// CMakeLists.txt.
#pragma once

// Generated by corrosion_add_cxxbridge — precision matches ATV_REAL.
#include "molrs_cxx/bridge.h"

namespace ATV {
/// @brief Chemical element — THE element-identity type, everywhere.
///
/// Defined once in molrs (`molrs::core::system::Element`, exported over the
/// CXX bridge as `molrs::Element`); Z is the enum value (H=1 .. Og=118).
/// Atomiverse defines no element type of its own.
using ::molrs::Element;
} // namespace ATV
